  ('9957c7a7-e0f4-4717-90ff-23f1fc826632', '3f947dff-141c-42ce-bd6d-d2abf6c09ebe', null, 'topic'::public.curated_course_node_type, 'Interpreting, Reporting, and Communicating Biostatistical Results', 'The final unit turns analysis into scientific communication. Students learn how to present methods, results, uncertainty, and limitations to clinical, biological, or public-health audiences.', 13),
  ('86418517-baa6-4fd4-979a-9f1d0d1b5028', '3f947dff-141c-42ce-bd6d-d2abf6c09ebe', '9957c7a7-e0f4-4717-90ff-23f1fc826632', 'subtopic'::public.curated_course_node_type, 'Statistical reporting', 'Students learn what belongs in a clear methods and results section.', 0),
