insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'The Analysis of Biological Data', 'Macmillan', 'Whitlock and Schluter. Biology-centered conceptual foundation, examples, experimental reasoning, and interpretation.', 0),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'Fundamentals of Biostatistics', 'Cengage', 'Rosner. Comprehensive probability, inference, regression, survival, and clinical/health applications.', 1),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'Biostatistics: The Bare Essentials', 'PMPH', 'Norman and Streiner. Approachable explanations for Health Professions and Public Health learners.', 2),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'Intuitive Biostatistics', 'Oxford University Press', 'Motulsky. Clear guidance on uncertainty, test interpretation, effect size, multiple comparisons, and common errors.', 3),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'Regression Methods in Biostatistics', 'Springer', 'Vittinghoff et al. Bridge to linear, logistic, survival, repeated-measures, and applied health modeling.', 4),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'OpenIntro Statistics', 'https://www.openintro.org/book/os/', 'Free readings, exercises, data sets, labs, slides, and conceptual review.', 5),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'textbook'::public.curated_course_resource_kind, 'OpenStax Introductory Statistics', 'https://openstax.org/details/books/introductory-statistics', 'Free foundation for description, probability, confidence intervals, tests, ANOVA, and regression.', 6),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'R for Data Science (2e)', 'https://r4ds.hadley.nz/', 'Free modern reference for importing, transforming, visualizing, and communicating data with R.', 7),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'R, RStudio, and Quarto', 'https://www.r-project.org/', 'Open statistical computing and reproducible reports. SAS may be substituted where program infrastructure requires it. Also https://posit.co/ and https://quarto.org/.', 8),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'UCLA OARC Statistical Consulting', 'https://stats.oarc.ucla.edu/', 'Applied guides for selecting and running methods in R, SAS, SPSS, and Stata.', 9),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'ASA GAISE College Report', 'https://www.amstat.org/education/guidelines-for-assessment-and-instruction-in-statistics-education-%28gaise%29-reports', 'Course-design benchmark for statistical thinking, real data, technology, active learning, assessment, and ethics.', 10),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'Johns Hopkins Statistical Methods in Public Health I', 'https://qa.publichealth.jhu.edu/course/42103', 'Official applied course objectives joining questions, probability, inference, displays, software, and interpretation.', 11),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'HHMI BioInteractive', 'https://www.biointeractive.org/classroom-resources', 'Authentic biology data, experiments, and classroom investigations.', 12),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'CDC Data and Epi Info', 'https://data.cdc.gov/', 'Surveillance and population-health data plus an accessible epidemiologic analysis tool. Also https://www.cdc.gov/epiinfo/.', 13),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'BMJ Statistics Notes', 'https://www.bmj.com/specialties/statistics-notes', 'Short articles on interpreting common statistical methods in medical research.', 14),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'EQUATOR Network', 'https://www.equator-network.org/', 'CONSORT, STROBE, PRISMA, and other design-specific reporting standards.', 15),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'website'::public.curated_course_resource_kind, 'NIH Rigor and Reproducibility', 'https://grants.nih.gov/policy-and-compliance/policy-topics/reproducibility', 'Authoritative expectations for transparent, rigorous biological and health research.', 16),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'youtube'::public.curated_course_resource_kind, 'StatQuest', 'https://www.youtube.com/@statquest', 'Clear explanations of inference, regression, classification, validation, and statistical pitfalls.', 17),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'youtube'::public.curated_course_resource_kind, 'MarinStatsLectures', 'https://www.youtube.com/@marinstatlectures', 'Worked methods and R practice for applied statistics.', 18),
  ('3f947dff-141c-42ce-bd6d-d2abf6c09ebe', 'youtube'::public.curated_course_resource_kind, 'Johns Hopkins Bloomberg SPH', 'https://www.youtube.com/@JohnsHopkinsSPH', 'Public-health context and alternative explanations for biostatistical methods.', 19);
